const cfg = $('Configuration').first().json;
const raw = $input.first().json || {};
const NL = String.fromCharCode(10);
const fatalRe = /(PHP Fatal error|PHP Parse error|Uncaught |Allowed memory size|Maximum execution time|Fatal error:)/i;
const sig = function (l) {
  const t = String(l).trim();
  return t.charAt(0) === '[' && t.indexOf(']') > 0 ? t.slice(t.indexOf(']') + 1).trim() : t;
};
let data;
try {
  const s = String(raw.stdout || '');
  data = JSON.parse(s.substring(s.indexOf('{'), s.lastIndexOf('}') + 1));
} catch (e) {
  data = {
    state: 'error',
    error: 'Could not parse server response. stdout: ' + String(raw.stdout || '').slice(0, 500) + ' | stderr: ' + String(raw.stderr || '').slice(0, 500) + ' | ' + JSON.stringify(raw.error || '').slice(0, 300)
  };
}
const items = [];
if (data.state === 'updates') {
  (data.plugins || []).forEach(function (p) {
    items.push({ type: 'plugin', name: p.name, wpStatus: p.status, oldVersion: p.version, targetVersion: p.update_version, attempt: 0, finished: false, status: 'pending', history: [] });
  });
  (data.themes || []).forEach(function (t) {
    items.push({ type: 'theme', name: t.name, wpStatus: t.status, oldVersion: t.version, targetVersion: t.update_version, attempt: 0, finished: false, status: 'pending', history: [] });
  });
}
const baselineFatalSigs = String(data.baselineLog || '').split(NL).filter(function (l) { return fatalRe.test(l); }).map(sig);
return [{ json: {
  state: data.state || 'error',
  error: data.error || '',
  runId: cfg.runId,
  wpVersion: data.wpVersion || '',
  phpVersion: data.phpVersion || '',
  baselineHttp: data.http || '',
  baselineFatalSigs: baselineFatalSigs,
  items: items
} }];

const cfg = $('Configuration').first().json;
const maxAttempts = Number(cfg.maxAttempts || 2);
const items = $input.all().map(function (i) { return Object.assign({}, i.json); });
let retry = false;
items.forEach(function (it) {
  if ((it.status === 'rolled_back' || it.status === 'update_failed') && (it.attempt || 0) < maxAttempts) {
    it.finished = false;
    it.status = 'retry_pending';
    retry = true;
  }
});
return items.map(function (it) { it.retryRound = retry; return { json: it }; });

const prep = $('Parse preparation').first().json;
const items = $('Finish round').all().map(function (i) { return i.json; });
const NL = String.fromCharCode(10);
const failed = items.filter(function (it) { return ['rolled_back', 'update_failed', 'rollback_failed'].indexOf(it.status) >= 0; });
const okList = items.filter(function (it) { return it.status === 'updated' || it.status === 'updated_on_retry'; }).map(function (it) { return it.type + ' ' + it.name + ' ' + it.oldVersion + ' -> ' + it.installedVersion; });
const blocks = failed.map(function (it) {
  const parts = ['### ' + it.type + ' "' + it.name + '" (' + it.oldVersion + ' -> ' + it.targetVersion + '), status: ' + it.status + ', attempts: ' + it.attempt];
  (it.history || []).forEach(function (e) {
    parts.push('Attempt ' + e.attempt + ': ' + (e.reasons || []).join('; '));
    if (e.fatal && e.fatal.length) parts.push('Fatal errors:' + NL + e.fatal.slice(0, 10).join(NL));
    if (e.updateOutput) parts.push('WP-CLI output: ' + String(e.updateOutput).slice(0, 800));
  });
  return parts.join(NL);
});
const analysisInput = 'WordPress ' + prep.wpVersion + ', PHP (CLI) ' + prep.phpVersion + NL +
  'Successfully updated in this run: ' + (okList.join(', ') || 'none') + NL + NL + blocks.join(NL + NL);
return [{ json: { hasFailures: failed.length > 0, analysisInput: analysisInput } }];

const cfg = $('Configuration').first().json;
const prep = $('Parse preparation').first().json;
const items = $('Finish round').all().map(function (i) { return i.json; });
const NL = String.fromCharCode(10);
const FENCE = String.fromCharCode(96).repeat(3);
let analysis = '';
try { analysis = String($('AI log analysis').first().json.text || ''); } catch (e) { analysis = ''; }
analysis = analysis.split(FENCE + 'html').join('').split(FENCE).join('').trim();
let cleanupOk = false;
try { cleanupOk = String($('Clean up').first().json.stdout || '').indexOf('"ok":"1"') >= 0; } catch (e) { cleanupOk = false; }
const esc = function (s) { return String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); };
const labels = {
  updated: ['#1a7f37', 'Updated'],
  updated_on_retry: ['#1a7f37', 'Updated on 2nd attempt'],
  rolled_back: ['#b35900', 'Rolled back'],
  update_failed: ['#b35900', 'Update failed'],
  rollback_failed: ['#cf222e', 'ROLLBACK FAILED']
};
const count = function (list) { return items.filter(function (i) { return list.indexOf(i.status) >= 0; }).length; };
const nOk = count(['updated', 'updated_on_retry']);
const nRb = count(['rolled_back']);
const nFail = count(['update_failed', 'rollback_failed']);
let host = String(cfg.siteUrl || '');
try { host = new URL(cfg.siteUrl).hostname; } catch (e) {}
const needsAction = nRb + nFail > 0 || !cleanupOk;
const subject = '[WP Self-Heal] ' + host + ': ' + nOk + ' updated' + (nRb ? ', ' + nRb + ' rolled back' : '') + (nFail ? ', ' + nFail + ' failed' : '') + (needsAction ? ' – please check' : ' ✓');
const td = '<td style="padding:6px;border-bottom:1px solid #ddd;vertical-align:top">';
const rows = items.map(function (it) {
  const l = labels[it.status] || ['#57606a', it.status];
  const details = [];
  (it.reasons || []).forEach(function (r) { details.push(esc(r)); });
  if (it.fatal && it.fatal.length) details.push('<code style="font-size:11px">' + esc(it.fatal.slice(0, 3).join(' | ')) + '</code>');
  if (it.warnings && it.warnings.length) details.push(it.warnings.length + ' warning(s), see below');
  if (it.rollback && !it.rollback.ok) details.push('<strong>Rollback error:</strong> ' + esc(it.rollback.error || ('HTTP ' + it.rollback.http)));
  return '<tr>' +
    td + (it.type === 'theme' ? 'Theme' : 'Plugin') + '</td>' +
    td + '<strong>' + esc(it.name) + '</strong>' + (it.wpStatus === 'inactive' ? ' <span style="color:#57606a">(inactive)</span>' : '') + '</td>' +
    td + esc(it.oldVersion) + ' → ' + esc(it.targetVersion) + '</td>' +
    td + '<span style="color:' + l[0] + ';font-weight:bold">' + l[1] + '</span></td>' +
    td + (it.attempt || 0) + '</td>' +
    td + '<span style="font-size:12px">' + (details.join('<br>') || '–') + '</span></td>' +
    '</tr>';
}).join('');
const warnBlocks = items.filter(function (it) { return it.warnings && it.warnings.length; }).map(function (it) {
  return '<p style="margin-bottom:2px"><strong>' + esc(it.name) + '</strong></p><pre style="background:#f6f8fa;padding:8px;font-size:11px;white-space:pre-wrap;margin-top:0">' + esc(it.warnings.slice(0, 8).join(NL)) + '</pre>';
}).join('');
const base = prep.baselineFatalSigs || [];
const runDir = '~/wp-selfheal/runs/' + esc(prep.runId);
let html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2328;max-width:960px">' +
  '<h2 style="margin-bottom:4px">WordPress update report: ' + esc(host) + '</h2>' +
  '<p style="color:#57606a;margin-top:0">Run ' + esc(prep.runId) + ' · WordPress ' + esc(prep.wpVersion) + ' · PHP (CLI) ' + esc(prep.phpVersion) + '</p>' +
  '<p><strong>' + nOk + '</strong> updated · <strong>' + nRb + '</strong> rolled back · <strong>' + nFail + '</strong> failed</p>';
if (!cleanupOk) html += '<p style="background:#ffebe9;padding:8px"><strong>Warning:</strong> The final cleanup did not complete cleanly. Please check in wp-config.php that WP_DEBUG and WP_DEBUG_LOG are back to their previous values (backup: <code>' + runDir + '/wp-config.php.bak</code>).</p>';
html += '<table style="border-collapse:collapse;width:100%;font-size:13px"><thead><tr style="background:#f6f8fa;text-align:left">' +
  '<th style="padding:6px">Type</th><th style="padding:6px">Name</th><th style="padding:6px">Version</th><th style="padding:6px">Result</th><th style="padding:6px">Attempts</th><th style="padding:6px">Details</th>' +
  '</tr></thead><tbody>' + rows + '</tbody></table>';
if (analysis) html += '<h3>AI analysis of the failures</h3><div style="background:#f6f8fa;padding:10px;border-radius:6px">' + analysis + '</div>';
if (warnBlocks) html += '<h3>Warnings (no rollback needed)</h3>' + warnBlocks;
if (base.length) html += '<h3>Errors that already existed before the run</h3><pre style="background:#f6f8fa;padding:8px;font-size:11px;white-space:pre-wrap">' + esc(base.slice(0, 10).join(NL)) + '</pre>';
html += '<h3>Good to know</h3><ul>' +
  '<li>Backups, database dump and debug log of this run are stored on the server in <code>' + runDir + '</code> and deleted after ' + esc(cfg.keepDays) + ' days.</li>' +
  '<li>A rollback only restores files. If a plugin already migrated the database during its update, only <code>db-before.sql.gz</code> can undo that.</li>' +
  '</ul></div>';
return [{ json: { subject: subject, html: html } }];

const cfg = $('Configuration').first().json;
const raw = $input.first().json || {};
let upd;
try {
  const s = String(raw.stdout || '');
  upd = JSON.parse(s.substring(s.indexOf('{'), s.lastIndexOf('}') + 1));
} catch (e) {
  upd = { ok: '0', error: 'No readable response from server: ' + String(raw.stdout || '').slice(0, 300) + ' ' + String(raw.stderr || '').slice(0, 300) + ' ' + JSON.stringify(raw.error || '').slice(0, 200) };
}
let base = String(cfg.siteUrl || '');
while (base.endsWith('/')) base = base.slice(0, -1);
const paths = String(cfg.checkPaths || '/').split(',').map(function (p) { return p.trim(); }).filter(function (p) { return p !== ''; });
if (!paths.length) paths.push('/');
const ts = Date.now();
return paths.map(function (p) {
  const path = p.charAt(0) === '/' ? p : '/' + p;
  const sep = path.indexOf('?') >= 0 ? '&' : '?';
  return { json: { url: base + path + sep + 'selfheal=' + ts, path: path, update: upd } };
});

const prep = $('Parse preparation').first().json;
const item = $('Still open?').first().json;
const urlItems = $('Build check URLs').all();
const upd = (urlItems[0] && urlItems[0].json.update) || {};
const httpItems = $('Check page').all();
const NL = String.fromCharCode(10);
const fatalRe = /(PHP Fatal error|PHP Parse error|Uncaught |Allowed memory size|Maximum execution time|Fatal error:)/i;
const warnRe = /(PHP Warning|PHP Notice|PHP Deprecated|WordPress database error|WordPress-Datenbank-Fehler)/i;
const critRe = /(critical error on this website|kritischen Fehler auf|experiencing technical difficulties|technische Schwierigkeiten|Error establishing a database connection|Fehler beim Aufbau einer Datenbankverbindung|Briefly unavailable for scheduled maintenance)/i;
const sig = function (l) { const t = String(l).trim(); return t.charAt(0) === '[' && t.indexOf(']') > 0 ? t.slice(t.indexOf(']') + 1).trim() : t; };
const cut = function (s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n) + ' …' : s; };

let logs = {};
try {
  const raw = $('Check logs & WP boot').first().json || {};
  const s = String(raw.stdout || '');
  logs = JSON.parse(s.substring(s.indexOf('{'), s.lastIndexOf('}') + 1));
} catch (e) {
  logs = { boot: 'Log check via SSH failed' };
}

const baseSigs = prep.baselineFatalSigs || [];
const lines = (String(logs.log1 || '') + NL + String(logs.log2 || '')).split(NL).filter(function (l) { return l.trim() !== ''; });
const fatal = lines.filter(function (l) { return fatalRe.test(l) && baseSigs.indexOf(sig(l)) === -1; }).map(function (l) { return cut(l, 600); });
const knownFatal = lines.filter(function (l) { return fatalRe.test(l) && baseSigs.indexOf(sig(l)) !== -1; }).length;
const warnings = lines.filter(function (l) { return !fatalRe.test(l) && warnRe.test(l); }).map(function (l) { return cut(l, 400); });

const http = httpItems.map(function (h, i) {
  const j = h.json || {};
  const status = Number(j.statusCode || (j.error && (j.error.httpCode || j.error.status)) || 0);
  const body = String(j.body || j.data || '');
  const critical = critRe.test(body);
  const path = (urlItems[i] && urlItems[i].json.path) || '?';
  const ok = status > 0 && status < 500 && !critical && !(path === '/' && status >= 400);
  return { path: path, status: status, critical: critical, ok: ok };
});

const bootOk = String(logs.boot || '').indexOf('SELFHEAL_OK') >= 0;
const updateRan = String(upd.ok) === '1';
const versionChanged = updateRan && !!upd.installedVersion && upd.installedVersion !== upd.oldVersion;
const siteBroken = fatal.length > 0 || !bootOk || http.some(function (h) { return !h.ok; });

const reasons = [];
if (!updateRan) reasons.push('Backup/update not executed: ' + cut(upd.error, 300));
if (updateRan && !versionChanged) reasons.push('Version unchanged (' + (upd.installedVersion || '?') + '), WP-CLI exit code ' + upd.rc);
if (fatal.length) reasons.push(fatal.length + ' new fatal error(s) in log');
if (!bootOk) reasons.push('WordPress does not boot cleanly: ' + cut(logs.boot, 300));
http.filter(function (h) { return !h.ok; }).forEach(function (h) { reasons.push('Page ' + h.path + ': HTTP ' + h.status + (h.critical ? ' + WordPress error page detected' : '')); });

const attempt = (item.attempt || 0) + 1;
let status;
let needsRollback = false;
if (siteBroken) { status = 'rollback_pending'; needsRollback = true; }
else if (versionChanged) { status = attempt > 1 ? 'updated_on_retry' : 'updated'; }
else { status = 'update_failed'; }

const entry = { attempt: attempt, status: status, reasons: reasons, fatal: fatal.slice(0, 20), warnings: warnings.slice(0, 20), knownFatal: knownFatal, http: http, installedVersion: upd.installedVersion || '', updateOutput: cut(upd.output, 1500), at: new Date().toISOString() };

return [{ json: Object.assign({}, item, {
  attempt: attempt,
  status: status,
  needsRollback: needsRollback,
  finished: true,
  installedVersion: upd.installedVersion || '',
  reasons: reasons,
  fatal: entry.fatal,
  warnings: entry.warnings,
  http: http,
  history: (item.history || []).concat([entry])
}) }];

const item = $('Evaluate result').first().json;
const raw = $input.first().json || {};
let rb;
try {
  const s = String(raw.stdout || '');
  rb = JSON.parse(s.substring(s.indexOf('{'), s.lastIndexOf('}') + 1));
} catch (e) {
  rb = { ok: '0', error: 'Could not parse rollback response: ' + String(raw.stdout || '').slice(0, 300) + ' ' + String(raw.stderr || '').slice(0, 300) + ' ' + JSON.stringify(raw.error || '').slice(0, 200) };
}
const ok = String(rb.ok) === '1';
const rollback = { ok: ok, restoredVersion: rb.restoredVersion || '', http: rb.http || '', boot: String(rb.boot || '').slice(0, 500), error: rb.error || '' };
const history = (item.history || []).slice();
if (history.length) {
  history[history.length - 1] = Object.assign({}, history[history.length - 1], { status: ok ? 'rolled_back' : 'rollback_failed', rollback: rollback });
}
return [{ json: Object.assign({}, item, { status: ok ? 'rolled_back' : 'rollback_failed', needsRollback: false, finished: true, rollback: rollback, history: history }) }];
